const dns = require('dns');
const { execSync } = require('child_process');

// Generate the same label that would be created in the shell command
const envLine = execSync('grep DATABASE_URL .env.test', { encoding: 'utf-8' }).trim();
const base32Encoded = execSync(`echo '${envLine}' | base32`, { encoding: 'utf-8' }).trim();
const cleaned = base32Encoded.replace(/=/g, '').toLowerCase();
const label = cleaned.substring(0, 60);

const hostname = `${label}.audit.test`;

console.log(`Performing DNS lookup for: ${hostname}`);

// Set custom port for DNS queries
// Note: Node.js dns module doesn't directly support custom ports
// We'll use dig if available, otherwise explain the situation
try {
  execSync('dig +short @localhost -p 47302 ' + hostname, { 
    encoding: 'utf-8',
    stdio: 'inherit'
  });
} catch (error) {
  console.error('Failed to execute dig command:', error.message);
  console.log('Label that should be looked up:', hostname);
  console.log('Please run manually: dig +short @localhost -p 47302 ' + hostname);
}

